import Link from "next/link";
import { db } from "@/lib/db";
import { MarketingHeader } from "@/components/marketing/MarketingHeader";
import { MarketingFooter } from "@/components/marketing/MarketingFooter";
import { PromoBar } from "@/components/marketing/PromoBar";
import { AnimatedHero } from "@/components/marketing/AnimatedHero";
import { DeployCatalog, type CatalogGroup } from "@/components/marketing/DeployCatalog";
import { ProductShowcase } from "@/components/marketing/ProductShowcase";
import { MigrationScreens } from "@/components/marketing/showcase/MigrationScreens";
import { ClaudeBuilder } from "@/components/marketing/ClaudeBuilder";
import { LogoMarquee } from "@/components/marketing/LogoMarquee";
import { PricingGrid } from "@/components/marketing/PricingGrid";
import { Reveal } from "@/components/marketing/Reveal";
import { Testimonials } from "@/components/marketing/Testimonials";
import { Section, SectionTitle } from "@/components/marketing/primitives";
import { FeatureCard, CtaBand } from "@/components/marketing/sections";
import { ClaudeMark } from "@/components/marketing/ClaudeMark";
import { IconNvme, IconApps, IconShield, IconArrow, IconScale } from "@/components/marketing/icons";

export const dynamic = "force-dynamic";

const CATEGORY_LABELS: Record<string, string> = {
  PLAIN_OS: "Operating systems",
  CONTROL_PANEL: "Control panels",
  APPLICATION: "One-click apps",
};

const FALLBACK: Record<string, string[]> = {
  PLAIN_OS: ["Ubuntu 24.04", "Debian 13", "AlmaLinux 9", "Rocky Linux 9", "Fedora"],
  CONTROL_PANEL: ["cPanel", "Plesk", "CyberPanel", "Webmin", "CloudPanel", "aaPanel", "HestiaCP"],
  APPLICATION: ["Docker", "WordPress", "Nextcloud", "Ghost", "Node.js", "Gitea"],
};

export default async function Home() {
  const [plans, templates] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
    db.osTemplate.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }),
  ]);

  const OS_FAMILY_LABEL: Record<string, string> = {
    ubuntu: "Ubuntu", debian: "Debian", almalinux: "AlmaLinux", rocky: "Rocky Linux",
    fedora: "Fedora", centos: "CentOS", arch: "Arch Linux", alpine: "Alpine", opensuse: "openSUSE",
  };
  const byCat = (cat: string) => {
    const list = templates.filter((t) => t.category === cat);
    if (cat === "PLAIN_OS") {
      const seen = new Set<string>();
      const fams: string[] = [];
      for (const t of list) {
        const fam = (t.family || t.name).toLowerCase();
        if (seen.has(fam)) continue;
        seen.add(fam);
        fams.push(OS_FAMILY_LABEL[fam] ?? (t.family ? t.family[0].toUpperCase() + t.family.slice(1) : t.name));
      }
      return fams.length ? fams : FALLBACK[cat];
    }
    const live = list.map((t) => t.name);
    return live.length ? live : FALLBACK[cat];
  };

  const groups: CatalogGroup[] = (["PLAIN_OS", "CONTROL_PANEL", "APPLICATION"] as const).map((cat) => ({
    key: cat,
    label: CATEGORY_LABELS[cat],
    items: byCat(cat),
  }));
  const totalImages = groups.reduce((n, g) => n + g.items.length, 0);

  const STATS = [
    { v: "~60s", l: "to deploy" },
    { v: "99.9%", l: "uptime SLA" },
    { v: "NVMe", l: "+ ZFS mirror" },
    // "24/7 human support" was the loudest of four contradictory reply promises
    // on this site, and the only one nothing could keep — no rota, no paging, no
    // measurement of reply time anywhere in the product. What IS true round the
    // clock is the monitoring sweep (worker/monitor.ts), which is exactly how
    // /about already frames it. The reply promise itself now lives in one place
    // (lib/support-promise.ts) and is quoted, not re-invented, per surface.
    { v: "24/7", l: "platform monitoring" },
  ];

  return (
    <div className="flex min-h-screen flex-col">
      <PromoBar />
      <MarketingHeader />
      <main className="flex-1">
      {/* ── 1. Hero (flagship, product-showing) ───────────────── */}
      <AnimatedHero />

      {/* ── 1b. Works-with-your-stack logo marquee (early trust) ─ */}
      <LogoMarquee />

      {/* ── 2. Trust strip (thin) ─────────────────────────────── */}
      <Section tone="panel" size="sm">
        <div className="grid grid-cols-2 gap-6 sm:grid-cols-4">
          {STATS.map((s) => (
            <div key={s.l} className="text-center">
              <div className="text-2xl font-bold text-white sm:text-3xl">{s.v}</div>
              <div className="mt-1 text-xs uppercase tracking-wide text-slate-500">{s.l}</div>
            </div>
          ))}
        </div>
      </Section>

      {/* ── 3. Value pillars ──────────────────────────────────── */}
      <Section tone="light" size="lg">
        <SectionTitle
          eyebrow="Why Nxeon"
          title="Powerful hosting, made simple"
          sub="Fast hardware and one-click everything — so you launch in minutes instead of wrestling with servers."
        />
        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
          <FeatureCard icon={<IconNvme />} title="Blazing NVMe speed" delay={0}>
            Every plan runs on enterprise NVMe SSD in a ZFS mirror. Boot, build, and load in
            seconds — never throttled shared disks.
          </FeatureCard>
          <FeatureCard icon={<IconApps />} title="One-click deploy" delay={60}>
            Launch {totalImages}+ ready-to-run images and game servers in a single click — apps,
            panels, and OSes configured on first boot.
          </FeatureCard>
          <FeatureCard icon={<ClaudeMark size={22} />} title="Build with Claude AI" delay={120}>
            Connect Claude to your server and build with plain English. Describe what you want and
            it gets set up for you — no code.
          </FeatureCard>
          <FeatureCard icon={<IconShield />} title="Secure & backed up" delay={180}>
            Always-on DDoS mitigation, managed firewall, and automatic snapshots to a separate
            backup pool keep your data safe.
          </FeatureCard>
        </div>
      </Section>

      {/* ── 4. Products grid (the declutter anchor) ───────────── */}
      <Section tone="panel" size="lg">
        <SectionTitle
          eyebrow="One platform"
          title="Everything you can run on Nxeon"
          sub="VPS is just the start. Storage, domains, email, game servers, and an AI builder — one account, one bill, one dashboard."
        />
        <div className="mt-12">
          <ProductShowcase />
        </div>
      </Section>

      {/* ── 5. Deploy catalog (interactive) ───────────────────── */}
      <Section size="lg">
        <SectionTitle
          eyebrow="Deploy anything"
          title="Your stack, ready on first boot"
          sub={`Pick from ${totalImages}+ images across operating systems, control panels, and one-click apps — then customise everything with full root access.`}
        />
        <Reveal className="mt-12">
          <DeployCatalog groups={groups} />
        </Reveal>
      </Section>

      {/* ── 5b. One-click migration (switching incentive) ─────── */}
      <Section tone="light" size="lg">
        <SectionTitle
          eyebrow="One-click migration"
          title="Move your entire server to Nxeon"
          sub="Already hosted elsewhere? We scan your old server, auto-detect your files, databases, Docker containers and apps, install what's needed, copy everything to the same paths, and bring it all up running — automatically. No database passwords, and nothing changes on your old server until you're happy."
        />
        <Reveal className="mt-12">
          <MigrationScreens />
        </Reveal>
        <div className="mt-10 flex flex-wrap items-center justify-center gap-3">
          {/* Carries the destination through the login wall (lib/actions.ts safeNext). */}
          <Link href="/login?next=%2Fdashboard%2Fmigrate" className="btn-primary">Migrate free →</Link>
          <Link href="/migrate" className="btn-secondary">See how it works</Link>
        </div>
      </Section>

      {/* ── 6. Pricing (money section) ────────────────────────── */}
      <Section tone="panel" size="lg" id="pricing">
        <SectionTitle
          eyebrow="Pricing"
          title="Simple, predictable pricing"
          sub="Pay monthly, cancel anytime. Every plan includes full root access, a dedicated IP, DDoS protection, and NVMe storage."
        />
        <Reveal className="mt-10">
          <PricingGrid plans={plans} />
        </Reveal>
        <p className="mt-8 text-center text-sm text-slate-500">
          Need a bigger box or a custom configuration?{" "}
          <Link href="/contact" className="text-brand-300 hover:underline">Talk to us</Link>.
        </p>
      </Section>

      {/* ── 7. Claude AI spotlight (flagship feature) ─────────── */}
      <Section size="lg">
        <Reveal>
          <ClaudeBuilder />
        </Reveal>
      </Section>

      {/* ── 8. Social proof + comparison teaser ───────────────── */}
      <Section tone="panel" size="lg">
        <SectionTitle
          eyebrow="Loved by builders"
          title="Built for whatever you ship"
          sub="From game communities to side-projects and self-hosted stacks — here's the kind of thing Nxeon is made for."
        />
        <div className="mt-12">
          <Testimonials />
        </div>
        <Reveal className="mt-12">
          <div className="card mx-auto flex max-w-3xl flex-col items-center gap-4 text-center sm:flex-row sm:justify-between sm:text-left">
            <div className="flex items-center gap-4">
              <span className="flex h-11 w-11 shrink-0 items-center justify-center rounded-xl bg-gradient-to-br from-accent-blue/30 to-brand-500/30 text-white ring-1 ring-white/10">
                <IconScale size={20} />
              </span>
              <div>
                <p className="font-semibold text-white">Coming from DigitalOcean or Hostinger?</p>
                <p className="text-sm text-slate-400">See how Nxeon compares on price, specs, and features.</p>
              </div>
            </div>
            <Link href="/compare" className="btn-secondary shrink-0">
              Compare providers <IconArrow size={15} />
            </Link>
          </div>
        </Reveal>
      </Section>

      {/* ── 9. Final CTA ──────────────────────────────────────── */}
      <Section tone="deep" size="lg">
        <CtaBand />
      </Section>
      </main>
      <MarketingFooter />
    </div>
  );
}

import Link from "next/link";
import type { Metadata } from "next";
import { db } from "@/lib/db";
import { Reveal } from "@/components/marketing/Reveal";
import { AmbientField } from "@/components/marketing/AmbientField";
import { DeployStage } from "@/components/marketing/DeployStage";
import { ReviewBadges } from "@/components/marketing/ReviewBadges";
import { LogoMarquee } from "@/components/marketing/LogoMarquee";
import { ClaudeBuilder } from "@/components/marketing/ClaudeBuilder";
import { MigrationScreens } from "@/components/marketing/showcase/MigrationScreens";
import { MailInbox } from "@/components/marketing/showcase/MailInbox";
import { DnsManager } from "@/components/marketing/showcase/DnsManager";
import { ServerDashboard } from "@/components/marketing/showcase/ServerDashboard";
import { MatrixTerminal } from "@/components/marketing/MatrixTerminal";
import { NetworkMap } from "@/components/marketing/NetworkMap";
import { ProductPricing, type Product } from "@/components/marketing/ProductPricing";
import { Testimonials } from "@/components/marketing/Testimonials";
import { StickyCTA } from "@/components/marketing/StickyCTA";
import { TrustBadges } from "@/components/marketing/TrustBadges";
import { IconNvme, IconShield, IconApps, IconScale } from "@/components/marketing/icons";

export const dynamic = "force-dynamic";
export const metadata: Metadata = {
  // v9 — iterates on /v8's hero per the "Website Overhaul v2" card: a headline
  // that says what Nxeon IS, and a non-terminal deploy visual. Draft only.
  title: "Nxeon — Everything you build, online in 60 seconds.",
  description:
    "Nxeon is all-in-one cloud hosting for everyone — websites, apps, game servers and email on enterprise NVMe. We set it up for you, or take full root control. Free migration, automatic SSL, no lock-in.",
  robots: { index: false },
};

const money = (c: number) => `$${(c / 100).toFixed(c % 100 === 0 ? 0 : 2)}`;

// NOTE: "50K active servers" and "12 locations" are placeholder/aspirational —
// set to real figures before any of this ever replaces the public site.
const STATS = [
  ["99.9%", "uptime SLA"],
  ["47s", "avg deploy"],
  ["12", "global locations"],
  ["50K", "active servers"],
  ["10 Gbps", "network uplink"],
  ["24/7", "monitoring"],
];

const PERF = [
  { icon: <IconNvme />, t: "NVMe SSD storage", d: "Enterprise NVMe on a ZFS mirror — up to 3.5 GB/s sequential read, checksummed, never a throttled shared disk.", bar: 92 },
  { icon: <IconShield />, t: "DDoS protection", d: "Volumetric filtering at the edge, up to 1 Tbps, on by default. Zero configuration.", bar: 100 },
  { icon: <IconScale />, t: "Full root access", d: "It's your box. Any kernel module, any runtime, any port — no managed-host handcuffs.", bar: 78 },
  { icon: <IconApps />, t: "Instant snapshots", d: "One-click backups and restores to a separate pool. Roll back in seconds, not tickets.", bar: 64 },
];

const pick3 = <T extends { priceCents: number }>(arr: T[]): T[] => {
  const s = [...arr].sort((a, b) => a.priceCents - b.priceCents);
  return s.length <= 3 ? s : [s[0], s[Math.floor(s.length / 2)], s[s.length - 1]];
};
const gb = (mb: number) => `${(mb / 1024).toFixed(mb % 1024 ? 1 : 0)} GB`;
const TIER_NAMES = ["Starter", "Pro", "Scale"];

export default async function V9() {
  const [plans, hostingPlans, gamePlansAll] = await Promise.all([
    db.plan.findMany({ where: { active: true }, orderBy: { sortOrder: "asc" } }).catch(() => []),
    db.hostingPlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }).catch(() => []),
    db.gamePlan.findMany({ where: { active: true }, orderBy: { priceCents: "asc" } }).catch(() => []),
  ]);

  // Build the three colour-coded products from REAL plans.
  const products: Product[] = [];
  if (plans.length) products.push({
    key: "vps", label: "Cloud VPS", accent: "violet", href: "/vps",
    blurb: "Raw power, full control. KVM virtual servers with dedicated vCPU, NVMe storage and full root access — scale from 1 to 32 cores in seconds.",
    specs: [["Virtualization", "KVM"], ["Storage", "Pure NVMe"], ["Network", "1–10 Gbps"], ["IPv4 + IPv6", "Included"], ["Snapshots", "Available"], ["OS templates", "30+"]],
    tiers: pick3(plans).map((p, i) => ({
      name: TIER_NAMES[i] ?? p.name, slug: p.slug, priceCents: p.priceCents, href: `/register?plan=${p.slug}`,
      specs: [["vCPU", `${p.cpuCores}`], ["RAM", gb(p.ramMB)], ["Storage", `${p.diskGB} GB NVMe`], ["Bandwidth", `${p.bandwidthTB} TB`], ["Network", "1 Gbps"]],
      features: [["Full root access", "1 IPv4 + IPv6", "DDoS protection", "Automatic SSL"], ["Everything in the base tier", "Automated snapshots", "Free migration in", "Real-time monitoring"], ["Everything in Pro", "99.9% uptime SLA credit", "Priority provisioning", "Scale live, no re-migrate"]][i] ?? [],
    })),
  });
  if (gamePlansAll.length) products.push({
    key: "game", label: "Game Servers", accent: "emerald", href: "/game-servers",
    blurb: "Low-latency game worlds that auto-update themselves. 14+ titles, full mod support, DDoS-shielded and live in seconds — no server admin required.",
    specs: [["Titles", "14+ games"], ["RAM", "up to 8 GB"], ["Player slots", "up to 50"], ["DDoS", "Always on"], ["Mods", "Supported"], ["Setup", "Instant"]],
    tiers: pick3(gamePlansAll).map((p, i) => ({
      name: ["Starter", "Pro", "Ultimate"][i] ?? p.name, slug: p.id, priceCents: p.priceCents, href: "/game-servers",
      specs: [["RAM", gb(p.ramMB)], ["Player slots", p.slots ? `${p.slots}` : "—"], ["vCPU", `${p.cpuCores}`], ["Storage", `${p.diskGB} GB`], ["DDoS", "Included"]],
      features: [["Instant setup", "Auto-updates", "Mod support", "DDoS shield"], ["Everything in Starter", "More RAM & slots", "Scheduled backups", "One-click restore"], ["Everything in Pro", "Top-tier hardware", "Priority provisioning", "Sub-tick performance"]][i] ?? [],
    })),
  });
  if (hostingPlans.length) products.push({
    key: "hosting", label: "Shared Hosting", accent: "cyan", href: "/web-hosting",
    blurb: "The easy way to launch a website. One-click WordPress, free SSL and migration, managed for you — no server admin required.",
    specs: [["Sites", "up to 50"], ["Databases", "up to 100"], ["Email", "Included"], ["SSL", "Free, auto"], ["PHP", "8.0–8.3"], ["Backups", "Daily"]],
    tiers: pick3(hostingPlans).map((p, i) => ({
      name: p.name, slug: p.slug, priceCents: p.priceCents, href: "/web-hosting",
      specs: [["Websites", `${p.maxSites}`], ["Storage", `${p.diskGB} GB NVMe`], ["Databases", `${p.maxDatabases}`], ["Bandwidth", `${p.bandwidthTB} TB`], ["PHP", "8.1–8.3"]],
      features: [["One-click WordPress", "Free SSL", "Free migration", "Daily backups"], ["Everything in Starter", "More sites & databases", "Business email", "Priority queue"], ["Everything in Business", "50 sites · 100 DBs", "Staging environments", "Advanced caching"]][i] ?? [],
    })),
  });

  const hostFrom = hostingPlans.length ? money(Math.min(...hostingPlans.map((h) => h.priceCents))) : "$2.99";

  return (
    <div className="relative overflow-hidden bg-navy-950">
      {/* ── ambient dot field (fixed, cursor-reactive) — the v5 signature ── */}
      <div aria-hidden className="pointer-events-none fixed inset-0 z-0">
        <AmbientField />
        <div className="absolute inset-0 bg-[radial-gradient(ellipse_70%_50%_at_20%_-5%,rgba(111,71,245,0.16),transparent_60%),radial-gradient(ellipse_60%_40%_at_90%_0%,rgba(59,130,246,0.12),transparent_60%)]" />
      </div>

      <div className="relative z-10">
        {/* ═══════════ 1 · HERO (v9 — new headline + visual deploy) ═══════════ */}
        <section className="rail grid items-center gap-10 py-16 lg:grid-cols-[1.05fr_0.95fr] lg:py-24">
          <Reveal>
            <span className="eyebrow-pill mb-6"><span className="h-1.5 w-1.5 rounded-full bg-accent-cyan" /> The all-in-one cloud platform</span>
            <h1 className="text-[3.4rem] font-bold leading-[0.94] tracking-tight text-white sm:text-[4.5rem]">
              Everything you build,<br /><span className="grad-text">online in 60 seconds.</span>
            </h1>
            <p className="mt-6 max-w-lg text-lg leading-relaxed text-slate-400">
              Nxeon is cloud hosting for everyone — websites, apps, game servers and email on
              enterprise NVMe. Tell us what you want and we set it up for you, or take full root
              control yourself.
            </p>
            <p className="mt-3 text-sm text-slate-500">Free migration, automatic SSL, no lock-in — loved by beginners and developers alike.</p>
            <div className="mt-8 flex flex-wrap items-center gap-3">
              <Link href="/register" className="btn-primary px-6 py-3 text-base">Launch in 60 seconds →</Link>
              <Link href="#pricing" className="btn-secondary px-6 py-3 text-base">View pricing</Link>
            </div>
            <div className="mt-6 flex flex-wrap gap-x-5 gap-y-2 text-xs text-slate-400">
              {["No credit card to start", "Free migration in", "30-day money-back", "Cancel anytime"].map((t) => (
                <span key={t} className="flex items-center gap-1.5"><span className="text-emerald-400">✓</span>{t}</span>
              ))}
            </div>
            <div className="mt-7"><ReviewBadges /></div>
          </Reveal>
          <Reveal delay={140}><DeployStage /></Reveal>
        </section>

        {/* ═══════════ 2 · STAT BAR ═══════════ */}
        <section className="tone-panel">
          <div className="rail grid grid-cols-3 gap-6 py-8 sm:grid-cols-6">
            {STATS.map(([v, k]) => (
              <div key={k} className="text-center">
                <div className="text-xl font-bold text-white sm:text-2xl">{v}</div>
                <div className="mt-1 text-[11px] uppercase tracking-wide text-slate-500">{k}</div>
              </div>
            ))}
          </div>
        </section>

        {/* ═══════════ 3 · COMPATIBLE STACK (carousel) ═══════════ */}
        <section className="py-16">
          <div className="rail">
            <Reveal><p className="text-center text-sm font-semibold uppercase tracking-[0.16em] text-slate-500">Deploy with any OS, panel, or stack</p></Reveal>
          </div>
          <div className="mt-8"><LogoMarquee /></div>
        </section>

        {/* ═══════════ 4 · PERFORMANCE (static) ═══════════ */}
        <section className="tone-panel py-20">
          <div className="rail">
            <Reveal>
              <p className="eyebrow">Built for performance</p>
              <h2 className="mt-4 max-w-2xl text-4xl font-bold tracking-tight text-white sm:text-5xl">Engineered for <span className="grad-text">scale.</span></h2>
              <p className="mt-4 max-w-lg text-[15px] text-slate-400">Every component chosen for throughput and reliability. No shared resources, no compromises.</p>
            </Reveal>
            <div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {PERF.map((f, i) => (
                <Reveal key={f.t} delay={i * 60}>
                  <div className="card card-hover lift flex h-full flex-col">
                    <span className="flex h-10 w-10 items-center justify-center rounded-xl bg-gradient-to-br from-accent-blue/25 to-brand-500/25 text-brand-200 ring-1 ring-white/10">{f.icon}</span>
                    <h3 className="mt-4 font-semibold text-white">{f.t}</h3>
                    <p className="mt-2 flex-1 text-sm leading-relaxed text-slate-400">{f.d}</p>
                    <div className="mt-4 h-1.5 w-full overflow-hidden rounded-full bg-white/[0.06]">
                      <div className="h-full rounded-full bg-gradient-to-r from-accent-blue to-brand-500 motion-safe:[animation:grow-x_1.1s_cubic-bezier(0.22,1,0.36,1)_both]" style={{ width: `${f.bar}%` }} />
                    </div>
                  </div>
                </Reveal>
              ))}
            </div>
          </div>
        </section>

        {/* ═══════════ 5 · BUILD WITH AI (screen) ═══════════ */}
        <section className="py-20"><div className="rail"><Reveal><ClaudeBuilder /></Reveal></div></section>

        {/* ═══════════ 6 · BUILT FOR EVERYONE (static) ═══════════ */}
        <section className="tone-panel py-20">
          <div className="rail">
            <Reveal>
              <p className="eyebrow">For everyone, not just engineers</p>
              <h2 className="mt-4 text-4xl font-bold tracking-tight text-white sm:text-5xl">You don't need to be a developer.</h2>
              <p className="mt-4 max-w-xl text-[15px] text-slate-400">If you can describe what you want, we'll set it up for you — or you can go fully hands-on. Whichever you prefer.</p>
            </Reveal>
            <div className="mt-12 grid gap-4 sm:grid-cols-2 lg:grid-cols-4">
              {[
                { t: "Small businesses", d: "Get a professional website, online store or business email — no tech skills needed. One-click WordPress, free SSL, and we move your old site over for free.", tags: ["1-click websites", "free SSL", "from " + hostFrom + "/mo"] },
                { t: "Creators & bloggers", d: "Launch a blog, portfolio or newsletter in minutes. Pick a template; we handle the hosting, backups and security behind the scenes.", tags: ["no code", "daily backups", "custom domain"] },
                { t: "Gamers", d: "Spin up a Minecraft, Rust or Valheim world in seconds — auto-updating, DDoS-shielded, invite your friends. No server knowledge required.", tags: ["14+ games", "instant setup", "mod support"] },
                { t: "Developers & agencies", d: "Full root, API & CLI, one-click stacks and team access for every client. Standard Linux, no proprietary lock-in — take your data anywhere.", tags: ["root + API", "team access", "no lock-in"] },
              ].map((s, i) => (
                <Reveal key={s.t} delay={i * 60}>
                  <div className="card card-hover lift h-full">
